import i18n, { InitOptions, TFuncKey, TFuncReturn, TFunction } from "i18next";
import { initReactI18next } from "react-i18next";
import { merge } from "lodash-es";
import { LabelType } from "@/core/labels/label-type";
import { expandDottedKeys } from "@/core/helpers/labels-helper";
import Labels from "./labels";

export type Language = "sv" | "en" | "nn";
export type Translation = TFunction<typeof defaultNamespace, undefined, typeof defaultNamespace>;

// LabelKey will contain all keys from the labels object, but we exclude those that would return an object.
// i18next supports returning objects, but we generally don't want to use that feature. If we do need it,
// skip the use of the LabelKey type. Read more: https://www.i18next.com/translation-function/objects-and-arrays
type AllKeys = TFuncKey<typeof defaultNamespace>;
export type LabelKey<AllowedReturnTypes = string> = keyof {
  [K in AllKeys as TFuncReturn<typeof defaultNamespace, K, string> extends AllowedReturnTypes ? K : never]: void;
};
export const defaultNamespace = "translation" as const;

const corei18n = i18n.createInstance();
corei18n.use(initReactI18next);

export const initLabels = (language: Language, labelsOverride?: Record<Language, Partial<LabelType>>) => {
  const i18NextOptions: InitOptions = {
    lng: language,
    supportedLngs: ["sv", "en", "nn"],
    fallbackLng: "sv",
    debug: false,
    interpolation: {
      escapeValue: false, // Not needed for React as it escapes by default
    },
    resources: {
      // Expand dot-separated keys and deep-merge, so nested labels can be
      // overridden individually without dropping their siblings.
      sv: {
        [defaultNamespace]: merge({}, Labels.sv, expandDottedKeys(labelsOverride?.sv)),
      },
      en: {
        [defaultNamespace]: merge({}, Labels.en, expandDottedKeys(labelsOverride?.en)),
      },
      nn: { [defaultNamespace]: expandDottedKeys(labelsOverride?.nn) },
    },
    fallbackNS: defaultNamespace,
  };

  corei18n.init(i18NextOptions);
};

export { corei18n };
