import { isArray, set } from "lodash-es";

type LabelOverrideContentful = {
  key: string;
  value: string;
};

export type LabelsOverrideContentful = {
  list: Array<LabelOverrideContentful>;
};

export type LabelsOverride = {
  [key: string]: string;
};

export const convertLabelsToMap = (labelsOverride: LabelsOverrideContentful) => {
  if (!labelsOverride || !isArray(labelsOverride.list)) {
    return {};
  }

  const initialValue: LabelsOverride = {};

  return labelsOverride.list.reduce((labels, item) => {
    if (item.key && item.value) {
      labels[item.key] = item.value;
    }
    return labels;
  }, initialValue);
};

/**
 * Turns dot-separated keys into a nested object,
 * e.g. { "a.b": value } => { a: { b: value } }.
 */
export const expandDottedKeys = (flatLabels: Record<string, unknown> = {}): Record<string, unknown> => {
  const nested: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(flatLabels)) {
    set(nested, key, value);
  }
  return nested;
};
