import { motion } from "framer-motion";
import styles from "./notification.module.less";
import {
  STANDARD_NOTIFICATION,
  SUCCESS_NOTIFICATION,
  WARNING_NOTIFICATION,
} from "@/core/components/primitives/notification-center/constants/notification-types";
import Icon from "@/core/components/primitives/icon/icon";
import { INotification } from "@/core/types/notifications/notifications";

type Props = Omit<INotification, "id" | "displayTime"> & {
  onClose: () => void;
};

const Notification = ({ headline, body, notificationType = STANDARD_NOTIFICATION, onClose }: Props) => {
  const getNotificationIcon = () => {
    switch (notificationType) {
      case SUCCESS_NOTIFICATION:
        return <Icon name="done" size="xxl" className={styles.leftIcon} />;
      case WARNING_NOTIFICATION:
        return <Icon name="error" size="xxl" className={styles.leftIcon} />;
      default:
        return <Icon name="info" size="xxl" className={styles.leftIcon} />;
    }
  };

  const getNotificationTypeClass = () => {
    switch (notificationType) {
      case SUCCESS_NOTIFICATION:
        return styles.success;
      case WARNING_NOTIFICATION:
        return styles.warning;
      default:
        return styles.standard;
    }
  };

  return (
    <motion.div className={[styles.wrapper, getNotificationTypeClass()].join(" ")} onClick={onClose}>
      <div className={styles.iconWrapper}>{getNotificationIcon()}</div>
      <div className={styles.textWrapper}>
        <h5 className={styles.headline}>{headline}</h5>
        {body && <p className={styles.body}>{body}</p>}
      </div>
      <Icon name="close" size="l" className={styles.closeIcon} />
      <motion.div className={styles.bottomBorder} />
    </motion.div>
  );
};

export default Notification;
