import { ADD_NOTIFICATION } from "@/core/components/primitives/notification-center/constants/actions";
import { INotification } from "../types/notifications/notifications";
import { GTMEvent } from "../types/tracking/google-tag-manager";

// These are moved into this file to avoid circular dependencies
export const EVENT_ON_MODAL_OPEN = "onModalOpen";
export const EVENT_ON_MODAL_CLOSE = "onModalClose";

/** A map from event names to their expected callback parameter type */
export type EventListenerMap = {
  gtmEvent: GTMEvent;
  onOrientationChange: Event;
  onResizeWindowHeight: number;
  onResizeWindowWidth: number;
  onScroll: number;
  onBeforeUnload: void;
  onHistoryAction: string;
  onToggleMenu: void;
  trackException: {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    exception: any;
    customMessage?: string;
  };
  trackPageview: { virtualPagePath: string; virtualPageTitle: string };
  [ADD_NOTIFICATION]: Pick<INotification, "notificationType" | "headline" | "body" | "displayTime">;
  [EVENT_ON_MODAL_OPEN]: number | string;
  [EVENT_ON_MODAL_CLOSE]: number | string;
  klarnaRedirectInitiated: void;

  // These are the old tracking events, and we should refrain from using them
  /** @deprecated */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  trackEvent: any;
  /** @deprecated */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  trackEcommerce: any;
};

class EventAggregator {
  events: Partial<{ [K in keyof EventListenerMap]: Array<(info: EventListenerMap[K]) => void> }> = {};

  subscribe<EventName extends keyof EventListenerMap>(
    eventName: EventName,
    callbackFunction: (info: EventListenerMap[EventName]) => void,
  ) {
    // Create the eventName's object if not yet created
    if (!this.events.hasOwnProperty.call(this.events, eventName)) {
      this.events[eventName] = [];
    }
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    const eventsArr = this.events[eventName]!;

    // Add the listener to queue
    const index = eventsArr.push(callbackFunction) - 1;

    // Provide handle back for removal of eventName
    return {
      remove: () => {
        delete eventsArr[index];
      },
    };
  }

  publish<EventName extends keyof EventListenerMap>(eventName: EventName, info: EventListenerMap[EventName]): void {
    // If the eventName doesn't exist, or there's no listeners in queue, just leave
    if (!this.events.hasOwnProperty.call(this.events, eventName)) {
      return;
    }
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    const eventsArr = this.events[eventName]!;

    // Cycle through events queue, fire!
    eventsArr.forEach(function (item) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      item(info !== undefined ? info : ({} as any));
    });
  }
}

const singleton = new EventAggregator();
export default singleton;
