//---- HASH PARAM PARTS ----//
// Helper functions and types for working with dynamic hash parameters in Storybook

/**
 * Filters an object to only include keys that start with "hash"
 * Used to create hash parameter types for Storybook stories
 *
 * @example
 * type MyHashParams = HashParams<{
 *   hashTheme: string;
 *   hashSize: number;
 *   hashMode: 'light' | 'dark';
 * }>;
 */
export type HashParams<StoryArgs extends Record<string, any>> = {
  // Loop through each object key in the story args

  // Filter: only keep keys that start with "hash" // Exclude this key // Preserve the original value type
[ObjectKey in keyof StoryArgs as ObjectKey extends `hash${string}` ? ObjectKey // Keep this key
: never]: StoryArgs[ObjectKey] };

/**
 * Extracts hash parameters from Storybook args and converts them to URL format
 * Transforms 'hashTheme' -> 'theme', filters out empty values
 */
const extractHashParams = (args: Record<string, any>): Record<string, any> => {
  const params: Record<string, any> = {};
  for (const [key, value] of Object.entries(args)) {
    if (key.startsWith("hash") && value !== undefined && value !== null && value !== "") {
      // Remove 'hash' prefix and convert to lowercase (e.g., 'hashTheme' -> 'theme')
      const paramName = key.charAt(4).toLowerCase() + key.slice(5);
      params[paramName] = value;
    }
  }
  return params;
};

/**
 * Reads URL hash parameters and converts them to Storybook arg defaults
 * Call this when defining story args to initialize from URL state
 */
export const getHashParamsDefaults = (): Record<string, any> => {
  if (typeof window === "undefined") return {};
  const hashString = window.location.hash.substring(1);
  if (!hashString) return {};
  try {
    const urlParams = decode(hashString);
    const storyArgs: Record<string, any> = {};

    // Parse JSON values and convert to Storybook format
    for (const [key, value] of Object.entries(urlParams)) {
      let parsedValue = value;

      // Try to parse JSON strings
      if (typeof value === "string") {
        try {
          parsedValue = JSON.parse(value);
        } catch {
          // Keep as string if parsing fails
        }
      }

      // Convert to hashXxx format for Storybook args
      const storyArgKey = `hash${key.charAt(0).toUpperCase()}${key.slice(1)}`;
      storyArgs[storyArgKey] = parsedValue;
    }
    return storyArgs;
  } catch {
    return {};
  }
};

/**
 * Decorator that syncs Storybook controls with URL hash parameters
 * Updates the URL whenever hash-prefixed args change
 */
export const setHashParams: Decorator<WithHashParamArgs<any>> = (Story, context) => {
  const params = extractHashParams(context.args);
  const hasParams = Object.keys(params).length > 0;
  if (typeof window !== "undefined") {
    if (!hasParams) {
      window.location.hash = "";
    } else {
      // Convert values to JSON strings for URL encoding
      const urlParams: Record<string, string> = {};
      for (const [key, value] of Object.entries(params)) {
        urlParams[key] = JSON.stringify(value);
      }
      window.location.hash = encode(urlParams);
    }
  }
  return <Story />;
};
export type WithHashParams<T extends ComponentType<any>, H extends Record<string, any> = {}> = ComponentType<ComponentProps<T> & WithHashParamArgs<H>>;
export type WithHashParamArgs<H extends Record<string, string | number | boolean | undefined> = {}> = HashParams<H>;
