//---- MOCKED DATE PARTS ----//
export const withMockedDate: Decorator<MockedDateArgs> = (Story, context) => {
  const mockedDate = new Date(context.args.mockedDate);
  if (isChromatic()) {
    // During Chromatic snapshots, freeze the clock to the exact mocked date so time-based
    // UI (e.g. the Queue Display countdown) is identical on every capture.
    // Without this the clock keeps ticking and the snapshot lands on a different
    // second each run, producing false diffs. See README > Snapshots & Chromatic.
    TodayHelper.getNow = () => mockedDate;
  } else {
    // Interactively (normal Storybook), keep time ticking from the mocked date so the
    // countdown etc. still animate and can be tested by hand.
    const diff = new Date().getTime() - mockedDate.getTime();
    TodayHelper.getNow = () => dayjs().subtract(diff, "milliseconds").toDate();
  }
  return <Story />;
};
export type WithMockedDate<T extends ComponentType<any>> = ComponentType<ComponentProps<T> & MockedDateArgs>;
export type MockedDateArgs = {
  mockedDate: Date;
};
