/**
 * Wraps the story in a QueryProvider that is otherwise set up in the sites.
 */
export const withQueryProvider: Decorator = Story => {
  return <QueryProvider>
      <Story />
    </QueryProvider>;
};

/**
 * Decorator that makes sure the story is always rendered with an empty query cache
 * for the given keys. The eviction happens synchronously during render — before
 * the child's `useQuery` reads from the cache — so the component always goes
 * through its loading state (important for play tests that observe placeholders /
 * loading UI, not just the final state).
 *
 * Uses `removeQueries` (evicts the cache entry entirely) rather than
 * `resetQueries` (which keeps showing stale data while refetching in background).
 */
export const withResetQueryCache: Decorator<WithResetQueryCacheArgs> = (Story, context) => {
  const queryClient = useQueryClient();
  const prevKeys = useRef<string>();
  const keysJson = JSON.stringify(context.args.resetQueryKeys);
  if (Array.isArray(context.args.resetQueryKeys) && keysJson !== prevKeys.current) {
    context.args.resetQueryKeys.forEach(key => {
      queryClient.removeQueries({
        queryKey: key
      });
    });
    prevKeys.current = keysJson;
  }
  return <Story />;
};
export type WithResetQueryCache<T extends ComponentType<any>> = ComponentType<ComponentProps<T> & WithResetQueryCacheArgs>;
export type WithResetQueryCacheArgs = {
  resetQueryKeys: Array<any>;
};
const withTheme: Decorator = (Story, context) => {
  if (context.globals.theme === "all") {
    return <>
        {themes.map(theme => <div className={theme.siteTheme}>
            <div className={multipleClassNames("story-wrapper", theme.class)}>
              <h2 className="story-theme-name">{theme.name}</h2>
              <ContentContainer>
                <NotificationContextProvider>
                  <NotificationContextConsumer>
                    {state => {
                  if (state.notifications.length > 0) {
                    return <NotificationCenter removeNotification={state.removeNotification} notifications={state.notifications} setValue={() => {}} />;
                  }
                  return null;
                }}
                  </NotificationContextConsumer>
                </NotificationContextProvider>
                <Story />
              </ContentContainer>
              <ModalPortal />
            </div>
          </div>)}
      </>;
  }
  const theme = getTheme(context.globals.theme);
  return <div className={multipleClassNames(theme?.siteTheme)}>
      <div className={multipleClassNames("story-wrapper", theme?.class)}>
        <ContentContainer>
          <NotificationContextProvider>
            <NotificationContextConsumer>
              {state => {
              if (state.notifications.length > 0) {
                return <NotificationCenter removeNotification={state.removeNotification} notifications={state.notifications} setValue={() => {}} />;
              }
              return null;
            }}
            </NotificationContextConsumer>
          </NotificationContextProvider>
          <Story />
        </ContentContainer>
        <ModalPortal />
      </div>
    </div>;
};

/** Used to set up the EventAggregators event that is otherwise set up in the sites. Please add more event publish events if needed */
const withEventListeners: Decorator = Story => {
  window.addEventListener("resize", e => {
    EventAggregator.publish("onResizeWindowWidth", window.innerWidth || document.documentElement.clientWidth || document.body.clientWidth);
  });
  return <Story />;
};
export const decorators = [withTheme, withEventListeners];

// Brand fonts are loaded over the network (Adobe Fonts / Typekit, see src/theming/README).
// They arrive after the page starts rendering, so a snapshot taken too early captures a
// fallback system font and Chromatic flags a false diff (see README > Snapshots & Chromatic
// > False diffs from fonts). Waiting on document.fonts.ready before each story renders makes
// every capture use the same, fully-loaded state.
const brandFontFamilies = ["source-sans-pro", "museo-sans", "montserrat", "raleway", "brandon-grotesque", "Brooklyn Samuels"];
const brandFontWeights = [400, 500, 600, 700];
export const loaders = [mswLoader(startMswWorker), async () => {
  if (typeof document === "undefined" || !document.fonts) return {};
  // Explicitly request every brand font/weight so document.fonts.ready has something to
  // wait for, even before the story's text has rendered. Missing weights just reject and
  // are ignored.
  await Promise.all(brandFontFamilies.flatMap(family => brandFontWeights.map(weight => document.fonts.load(`${weight} 1em "${family}"`).catch(() => undefined))));
  await document.fonts.ready;
  return {};
}];
