type VariantType = "prop" | "state" | "theme" | "other";

/** Lays out several variants in a vertical list with consistent spacing. */
export const ShowcaseLayout = ({
  title,
  variantType,
  children
}: {
  /** What variants are being showcased
   * - prop (name of prop)
   * - state (name/description of state)
   * - theme (name of theme)
   * - other (description of type, within parentheses) */
  title: string;
  /** What type of variant it is, if 'other': add description of type within parentheses */
  variantType: VariantType;
  /** The variants to render */
  children: ReactNode;
}) => <div style={{
  display: "flex",
  flexDirection: "column"
}}>
    <div>
      <h2 style={{
      marginBottom: 0
    }}>
        Variants of: {title} {variantType !== "other" && `(${variantType})`}
      </h2>
      <hr style={{
      width: "100%"
    }} />
    </div>
    {children}
  </div>;

/** Renders a single variant with a caption describing it and a horizontal rule separating it from other variants */
