import styles from "./parks-button.module.less";
import { AnchorHTMLAttributes, forwardRef } from "react";
import Link from "@/core/components/primitives/link/link";
import Icon from "@/core/components/primitives/icon/icon";
import { IconName } from "@/core/components/primitives/icon/icon";
import { Props as IconProps } from "@/core/components/primitives/icon/icon";
import { multipleClassNames } from "@/core/helpers/string-helper";
import { CallToAction } from "@/core/types";

type ButtonSize = "small" | "medium" | "large";

type Props = {
  className?: string;
  size?: ButtonSize;
  isFullWidth?: boolean;
  /**
   * @important buttons should only be disabled during actions, aka never to indicate that anything is missing/uncompleted.
   * Use other components for that (banner, form validation etc.)
   * */
  isDisabled?: boolean;
  label?: string;
  ariaLabel?: string;
  labelClass?: string;
  /** @deprecated Use iconRightNew instead */
  iconRight?: string;
  /** @deprecated Use iconLeftNew instead */
  iconLeft?: string;
  /** @deprecated Use iconCenterNew instead */
  iconCenter?: string;
  iconRightNew?: IconName;
  iconLeftNew?: IconName;
  iconCenterNew?: IconName;
  iconSize?: IconProps["size"];
  complementary?: boolean;
  testId?: string;
  contentfulLabelId?: string;
};

export type ParksButtonType =
  | "PrimaryButton"
  | "PrimaryButtonLink"
  | "SecondaryButton"
  | "SecondaryButtonLink"
  | "GhostButton"
  | "GhostButtonLink"
  | "OutlineButton"
  | "OutlineButtonLink";

export type ButtonProps = Props & Pick<React.ComponentProps<"button">, "onClick" | "autoFocus">;

export type ButtonLinkProps = Props & {
  openInNewTab?: boolean;
  url?: string;
} & Pick<AnchorHTMLAttributes<HTMLAnchorElement>, "onClick">;

const PrimaryButton = forwardRef<HTMLButtonElement, ButtonProps>(({ className, complementary, ...rest }, ref) => {
  return (
    <Button
      ref={ref}
      className={multipleClassNames(complementary ? styles.primaryComplementary : styles.primary, className)}
      {...rest}
    />
  );
});

PrimaryButton.displayName = "PrimaryButton";
export { PrimaryButton };

export const PrimaryButtonLink = ({ className, complementary, ...rest }: ButtonLinkProps) => (
  <ButtonLink
    className={multipleClassNames(complementary ? styles.primaryComplementary : styles.primary, className)}
    {...rest}
  />
);

const SecondaryButton = forwardRef<HTMLButtonElement, ButtonProps>(({ className, complementary, ...rest }, ref) => {
  return (
    <Button
      ref={ref}
      className={multipleClassNames(complementary ? styles.secondaryComplementary : styles.secondary, className)}
      {...rest}
    />
  );
});

SecondaryButton.displayName = "SecondaryButton";
export { SecondaryButton };

export const SecondaryButtonLink = ({ className, complementary, ...rest }: ButtonLinkProps) => (
  <ButtonLink
    className={multipleClassNames(complementary ? styles.secondaryComplementary : styles.secondary, className)}
    {...rest}
  />
);
export const GhostButton = forwardRef<HTMLButtonElement, Omit<ButtonProps, "complementary" | "borderOnly">>(
  ({ className, ...rest }, ref) => (
    <Button ref={ref} className={multipleClassNames(styles.ghost, className)} {...rest} />
  ),
);

GhostButton.displayName = "GhostButton";

export const GhostButtonLink = ({ className, ...rest }: Omit<ButtonLinkProps, "complementary" | "borderOnly">) => (
  <ButtonLink className={multipleClassNames(styles.ghost, className)} {...rest} />
);

export const OutlineButton = forwardRef<HTMLButtonElement, Omit<ButtonProps, "complementary" | "borderOnly">>(
  ({ className, ...rest }, ref) => (
    <Button ref={ref} className={multipleClassNames(styles.outline, className)} {...rest} />
  ),
);

OutlineButton.displayName = "OutlineButton";

export const OutlineButtonLink = ({ className, ...rest }: Omit<ButtonLinkProps, "complementary" | "borderOnly">) => (
  <ButtonLink className={multipleClassNames(styles.outline, className)} {...rest} />
);

const getCommonClasses = ({
  size,
  isFullWidth,
  isDisabled,
  label,
  iconLeftNew,
  iconRightNew,
  iconCenterNew,
}: Pick<Required<ButtonProps>, "size"> &
  Pick<
    ButtonProps,
    "isFullWidth" | "isDisabled" | "label" | "iconLeftNew" | "iconRightNew" | "iconCenterNew"
  >): string =>
  multipleClassNames(
    styles.common,
    styles[size],
    isFullWidth && styles.fullWidth,
    isDisabled && styles.disabled,
    !label && (iconLeftNew || iconRightNew || iconCenterNew) && styles.iconWithoutLabel,
  );

/**Supports both old and new icons to not make a breaking change.
 * Once all references of the Buttons in all repos have moved to new icons, the old icon props can be removed
 */
const Content = ({
  iconRight,
  iconLeft,
  iconCenter,
  iconRightNew,
  iconLeftNew,
  iconCenterNew,
  iconSize = "l",
  label,
  labelClass,
}: Pick<
  Props,
  | "iconRight"
  | "iconLeft"
  | "iconCenter"
  | "iconRightNew"
  | "iconLeftNew"
  | "iconCenterNew"
  | "iconSize"
  | "label"
  | "labelClass"
>) => {
  return (
    <>
      {iconLeft && !iconLeftNew && <span className={`${styles.iconLeft} ${iconLeft}`} />}
      {iconLeftNew && !iconLeft && <Icon name={iconLeftNew} className={styles.iconLeft} size={iconSize} />}
      <span data-is-empty={!label} className={labelClass}>
        {label}
      </span>
      {iconRight && !iconRightNew && <span className={`${styles.iconRight} ${iconRight}`} />}
      {iconRightNew && !iconRight && <Icon name={iconRightNew} className={styles.iconRight} size={iconSize} />}
      {iconCenter && !iconCenterNew && <span className={iconCenter} />}
      {iconCenterNew && !iconCenter && <Icon name={iconCenterNew} size={iconSize} />}
    </>
  );
};

export const buttonLinkIsInternal = (url: string): boolean => url.startsWith("/");

export const buttonUrlFromCallToAction = (callToActionButton?: CallToAction) => {
  return (
    callToActionButton?.externalUrl ??
    callToActionButton?.internalLink?.slug ??
    callToActionButton?.asset?.file.url ??
    ""
  );
};

export const ButtonLink = ({
  className,
  size = "medium",
  isFullWidth,
  isDisabled,
  label,
  labelClass,
  iconLeft,
  iconRight,
  iconCenter,
  iconLeftNew,
  iconRightNew,
  iconCenterNew,
  iconSize,
  openInNewTab,
  url,
  onClick,
  testId,
}: ButtonLinkProps) => {
  const commonClasses = getCommonClasses({
    size,
    isFullWidth,
    isDisabled,
    label,
    iconLeftNew,
    iconRightNew,
    iconCenterNew,
  });

  const ButtonContent = (
    <Content
      iconLeft={iconLeft}
      iconRight={iconRight}
      iconCenter={iconCenter}
      iconLeftNew={iconLeftNew}
      iconRightNew={iconRightNew}
      iconCenterNew={iconCenterNew}
      iconSize={iconSize}
      label={label}
      labelClass={labelClass}
    />
  );

  // Prevent event bubbling and default action for disabled fake link buttons
  const handleDisabledClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (isDisabled) {
      e.preventDefault();
      e.stopPropagation();
    }
  };

  return url ? (
    <Link
      className={[styles.link, className ?? "", commonClasses].join(" ")}
      openInNewTab={openInNewTab}
      internalLink={url && buttonLinkIsInternal(url) ? url : undefined}
      externalLink={url && buttonLinkIsInternal(url) ? undefined : url}
      onClick={onClick}
      data-testid={testId}
    >
      {ButtonContent}
    </Link>
  ) : (
    <button
      role="link"
      className={[styles.link, className ?? "", commonClasses].join(" ")}
      aria-disabled={isDisabled}
      onClick={handleDisabledClick}
      data-testid={testId}
    >
      {ButtonContent}
    </button>
  );
};

const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      onClick,
      size = "medium",
      isFullWidth,
      isDisabled,
      label,
      ariaLabel,
      labelClass,
      iconLeft,
      iconRight,
      iconCenter,
      iconLeftNew,
      iconRightNew,
      iconCenterNew,
      iconSize,
      testId,
      contentfulLabelId,
      ...rest
    },
    ref,
  ) => {
    const commonClasses = getCommonClasses({
      size,
      isFullWidth,
      isDisabled,
      label,
      iconLeftNew,
      iconRightNew,
      iconCenterNew,
    });
    return (
      <button
        ref={ref}
        className={[styles.button, className ?? "", commonClasses].join(" ")}
        onClick={onClick}
        disabled={isDisabled}
        data-testid={testId}
        data-contentful-label-id={contentfulLabelId}
        aria-label={ariaLabel}
        {...rest}
      >
        <Content
          iconLeft={iconLeft}
          iconRight={iconRight}
          iconCenter={iconCenter}
          iconLeftNew={iconLeftNew}
          iconRightNew={iconRightNew}
          iconCenterNew={iconCenterNew}
          iconSize={iconSize}
          label={label}
          labelClass={labelClass}
        />
      </button>
    );
  },
);

Button.displayName = "Button";

export const UnstyledButton = ({ className, ...rest }: ButtonProps) => {
  return <Button className={multipleClassNames(className)} {...rest} />;
};

export default Button;
