import { corei18n } from "../labels/i18n";

// @ts-strict-ignore
type ContinueShoppingLinkProps = {
  title: string;
  internalLink: {
    slug: string;
  };
};

export type ECommerceConfigProps = {
  currency: any;
  culture: any;
  currencyDisplayName?: any;
  cartLabel?: any;
  cartArticleLabel?: any;
  cartArticlesLabel?: any;
  cartIsEmptyLabel?: any;
  /**  @deprecated use t("cartSummary") instead*/
  cartSummeryLabel?: any;
  removeFromCartLabel?: any;
  addToCartLabel?: any;
  addReactivateCardToCartLabel?: any;
  addedToCartLabel?: any;
  continueLabel?: any;
  cancelLabel?: any;
  jetshopCheckoutUrl?: any;
  continueShoppingLabel?: string;
  continueShoppingLink?: ContinueShoppingLinkProps;
  errorMessages?: any;
  cardNumberInputLabel?: any;
  cardNumberInputHelpText?: any;
  emailInputLabel?: any;
  emailInputHelpText?: any;
  admissionAddToCartLabel?: any;
  bookShowAddToCartLabel?: any;
  bookShowOutOfStock?: any;
  upsellPageUrl?: any;
  onlyValidText?: any;
  seasonPassPageConfig?: any;
};

class ECommerceHelper {
  jetshop: ECommerceConfigProps;

  constructor() {
    this.jetshop = {
      currency: null,
      culture: null,
    };
  }

  initJetshop(eConfig) {
    this.jetshop = {
      currency: eConfig.jetshopCurrency ? eConfig.jetshopCurrency : "",
      culture: eConfig.jetshopCulture ? eConfig.jetshopCulture : "",
      currencyDisplayName: eConfig.currencyDisplayName ? eConfig.currencyDisplayName : "",
      cartLabel: eConfig.cartLabel ? eConfig.cartLabel : "",
      cartArticleLabel: eConfig.cartArticleLabel ? eConfig.cartArticleLabel : "",
      cartArticlesLabel: eConfig.cartArticlesLabel ? eConfig.cartArticlesLabel : "",
      cartIsEmptyLabel: eConfig.cartIsEmptyLabel ? eConfig.cartIsEmptyLabel : "",
      cartSummeryLabel: eConfig.cartSummeryLabel ? eConfig.cartSummeryLabel : "",
      removeFromCartLabel: eConfig.removeFromCartLabel ? eConfig.removeFromCartLabel : "",
      addToCartLabel: eConfig.addToCartLabel ? eConfig.addToCartLabel : "",
      addReactivateCardToCartLabel: eConfig.addReactivateCardToCartLabel ? eConfig.addReactivateCardToCartLabel : "",
      addedToCartLabel: eConfig.addedToCartLabel ? eConfig.addedToCartLabel : "",
      continueLabel: eConfig.continueLabel ? eConfig.continueLabel : "",
      cancelLabel: eConfig.cancelLabel ? eConfig.cancelLabel : "",
      jetshopCheckoutUrl: eConfig.jetshopCheckoutUrl ? eConfig.jetshopCheckoutUrl : "",
      continueShoppingLabel: eConfig.continueShoppingLabel ? eConfig.continueShoppingLabel : "",
      continueShoppingLink: eConfig.continueShoppingLink ? eConfig.continueShoppingLink : "",
      errorMessages: eConfig.jetshopErrorMessages ? eConfig.jetshopErrorMessages.list : "",
      cardNumberInputLabel: eConfig.cardNumberInputLabel ? eConfig.cardNumberInputLabel : "",
      cardNumberInputHelpText: eConfig.cardNumberInputHelpText ? eConfig.cardNumberInputHelpText : "",
      emailInputLabel: eConfig.emailInputLabel ? eConfig.emailInputLabel : "",
      emailInputHelpText: eConfig.emailInputHelpText ? eConfig.emailInputHelpText : "",
      admissionAddToCartLabel: eConfig.admissionAddToCartLabel ? eConfig.admissionAddToCartLabel : "",
      bookShowAddToCartLabel: eConfig.bookShowAddToCartLabel ? eConfig.bookShowAddToCartLabel : "",
      bookShowOutOfStock: eConfig.bookShowOutOfStock ? eConfig.bookShowOutOfStock : "",
      upsellPageUrl: eConfig.upsellPage ? eConfig.upsellPage.slug : null,
      onlyValidText: eConfig.onlyValidText ? eConfig.onlyValidText : null,
      seasonPassPageConfig: eConfig.seasonPassPageConfig ? eConfig.seasonPassPageConfig : null,
    };
  }

  /**
   * Returns human readable error message
   * @param {string} error ex. "ITEM_NOT_FOUND"
   * @param {string} fallback
   * @returns {string} message
   */
  getErrorMessage(error: any, fallback?: any) {
    if (!fallback) {
      fallback = corei18n.t("somethingWentWrong");
    }

    const errorMessages = this.jetshop.errorMessages;
    const errorKey = typeof error === "string" ? error : this.getErrorKeyFromObject(error);

    if (errorKey && errorMessages instanceof Array && errorMessages.length) {
      const message = errorMessages.find((item) => item.key === errorKey);
      if (message) {
        return message.value;
      } else {
        const defaultMessage = errorMessages.find((item) => item.key && item.key.toLowerCase() === "default");
        return defaultMessage ? defaultMessage.value : fallback;
      }
    }
    return fallback;
  }

  getErrorKeyFromObject(obj) {
    if (typeof obj !== "object") {
      return null;
    }

    if (obj.message) {
      return obj.message;
    }

    if (obj.Message) {
      return obj.Message;
    }

    if (obj.status) {
      return obj.status;
    }

    if (obj.Status) {
      return obj.Status;
    }

    return null;
  }

  getJetshopConfig() {
    return this.jetshop;
  }
}

const helper = new ECommerceHelper();
export default helper;
