/**
 * @param {String} string String
 * @param {String | Array} replacements replacements matching index in array to {n} in string,
 *  example:  insertIntoString('{0} is a name. {1} is an animal.', "Fred", "Cow") => Fred is a name. Cow is an animal.
 * @returns {String} returns a new string with the corresponding {n} changed to the corresponding arguments
 */
export const insertIntoString = (string: string, replacements: string | number | Array<string | number>): string => {
  const newString = string.replace(/{(\d+)}/g, (word, number) => {
    if (typeof replacements === "string" || typeof replacements === "number") {
      return replacements.toString();
    } else if (replacements instanceof Array && replacements[number] !== undefined) {
      return replacements[number].toString();
    }
    return word;
  });
  return newString;
};

/**
 * Try to find replace key in string with a value
 * @param string string to be formatted
 * @param replacements Record of key and value to be replaced
 * @returns string
 */
export const tryReplaceInString = (string: string, replacements: Record<string, string>): string => {
  const newString = string.replace(/{(\w+)}/g, (word, key) => {
    if (replacements[`{${key}}`] !== undefined) {
      return replacements[`{${key}}`];
    }
    return word;
  });
  return newString;
};

export const addLeadingZero = (number: string | number): string => {
  const numberString = number.toString();
  return numberString.length < 2 ? `0${numberString}` : numberString;
};

/**
 * @param {String} string
 * @param {number} maxCharacters
 * @returns {String} Shortened string with ... if it's larger than maxCharacters
 */
export const truncateWithDots = (string: string, maxCharacters = 80) => {
  if (string.length > maxCharacters) return string.substring(0, maxCharacters) + "...";
  else return string;
};

export const capitalizeFirstLetter = (str: string) => {
  return str ? str.charAt(0).toUpperCase() + str.slice(1) : str;
};

export const lowerCaseAndRemoveSpecialCharacters = (text: string) => {
  return text.toLowerCase().replace(/[^a-zA-Zé]/g, "");
};

export const multipleClassNames = (...args: Array<string | boolean | null | undefined>) => {
  return args.filter(Boolean).join(" ");
};
