// @ts-strict-ignore
import styles from "./add-to-cart-notification.module.less";
import {
  OutlineButton,
  PrimaryButton,
  SecondaryButton,
  SecondaryButtonLink,
} from "@/core/components/primitives/parks-button/parks-button";
import { ECommerceHelper } from "@/core/helpers";
import { useTranslation } from "react-i18next";

const AddToCartNotification = ({ headline, body, onClose, setValue }) => {
  const { t } = useTranslation();

  const jetshopConfig = ECommerceHelper.getJetshopConfig();
  const continueShoppingLink = jetshopConfig?.continueShoppingLink;
  const slug = continueShoppingLink?.internalLink?.slug;
  const continueLabel = continueShoppingLink?.title ?? t("continueShopping");

  const handleCartButtonClick = () => {
    setValue({ showCart: true });
  };

  return (
    <div className={styles.wrapper}>
      <OutlineButton className={styles.closeButton} iconLeftNew="close" onClick={() => onClose()} />
      <div className={styles.textWrapper}>
        <h3 className={styles.headline}>{headline}</h3>
        <p className={styles.body}>{body} </p>
      </div>
      <div className={styles.buttonWrapper}>
        <span onClick={() => onClose()}>
          {slug ? (
            <SecondaryButtonLink label={continueLabel} className={styles.continueShoppingButton} url={slug} />
          ) : (
            <SecondaryButton isFullWidth={false} label={continueLabel} className={styles.continueShoppingButton} />
          )}
        </span>
        <PrimaryButton
          label={t("toCheckout")}
          onClick={() => {
            handleCartButtonClick();
            onClose();
          }}
          className={styles.toCartButton}
        />
      </div>
    </div>
  );
};

export default AddToCartNotification;
